import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.B-qY3dMa.js";const u=JSON.parse('{"title":"Claude Code 省 Token 实战：7 个技巧把成本砍掉一半","description":"","frontmatter":{},"headers":[],"relativePath":"tips/claude-code-save-token.md","filePath":"tips/claude-code-save-token.md","lastUpdated":1780054548000}'),d={name:"tips/claude-code-save-token.md"};function s(r,e,l,i,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-code-省-token-实战-7-个技巧把成本砍掉一半" tabindex="-1">Claude Code 省 Token 实战：7 个技巧把成本砍掉一半 <a class="header-anchor" href="#claude-code-省-token-实战-7-个技巧把成本砍掉一半" aria-label="Permalink to &quot;Claude Code 省 Token 实战：7 个技巧把成本砍掉一半&quot;">​</a></h1><blockquote><p>本文整理自多位开发者的实战经验，综合以下来源：</p><ul><li><a href="https://www.cnblogs.com/zjdxr-up/p/19744977" target="_blank" rel="noreferrer">Claude Code Token 收费估算 · 博客园</a></li><li><a href="https://segmentfault.com/a/1190000047785121" target="_blank" rel="noreferrer">7 个实用技巧，让 Claude Code 的 Token 消耗暴降 80% · SegmentFault</a></li><li><a href="https://zhuanlan.zhihu.com/p/2020558938043598319" target="_blank" rel="noreferrer">Claude Code 太烧钱了？5 招把 token 成本砍了一半 · 知乎</a></li><li><a href="https://academy.claude-code.club/practical-skills/commands/save-tokens" target="_blank" rel="noreferrer">CC Academy 省钱秘笈</a></li></ul><p>原文观点仅代表作者个人意见。</p></blockquote><hr><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>很多人用 Claude Code 都有过这种困惑：明明只写了几个小功能，Token 就没了；一天随随便便花了几十美元，甚至怀疑&quot;比请个实习生还贵&quot;。</p><p>其实 Token 烧得快，根源只有一个：<strong>上下文在悄悄膨胀</strong>。每一轮对话，Claude 都要把之前所有的历史记录重新读一遍，历史越长，每条消息就越贵。本文整理了 7 个立竿见影的技巧，帮你把成本控制在合理范围内。</p><hr><h2 id="一、先搞清楚钱花在哪了" tabindex="-1">一、先搞清楚钱花在哪了 <a class="header-anchor" href="#一、先搞清楚钱花在哪了" aria-label="Permalink to &quot;一、先搞清楚钱花在哪了&quot;">​</a></h2><p>一次典型的 Claude Code 开发会话，Token 构成大概是这样：</p><table tabindex="0"><thead><tr><th>消耗来源</th><th>占比</th></tr></thead><tbody><tr><td>对话历史累积</td><td><strong>53%</strong></td></tr><tr><td>读取的源文件</td><td>20%</td></tr><tr><td>AI 响应内容</td><td>20%</td></tr><tr><td>系统提示 / CLAUDE.md</td><td>3%</td></tr><tr><td>工具调用（Bash / 编辑器）</td><td>4%</td></tr></tbody></table><p><strong>关键结论：超过一半的 Token 花在了&quot;对话历史&quot;上</strong>，而不是你真正提的问题。这是最值得优化的地方。</p><hr><h2 id="二、7-个省钱技巧" tabindex="-1">二、7 个省钱技巧 <a class="header-anchor" href="#二、7-个省钱技巧" aria-label="Permalink to &quot;二、7 个省钱技巧&quot;">​</a></h2><h3 id="技巧-1-用-compact-压缩上下文-节省-80" tabindex="-1">技巧 1：用 <code>/compact</code> 压缩上下文（节省 80%+） <a class="header-anchor" href="#技巧-1-用-compact-压缩上下文-节省-80" aria-label="Permalink to &quot;技巧 1：用 `/compact` 压缩上下文（节省 80%+）&quot;">​</a></h3><p><code>/compact</code> 会把之前的对话历史从 25000 Token 压缩成约 3000 Token 的摘要，节省率超过 80%。</p><p><strong>什么时候用：</strong></p><ul><li>对话超过 5 轮</li><li>完成一个子任务、准备开始下一个</li><li>感觉 Claude 响应变慢了（上下文太长会拖慢速度）</li></ul><p>还可以带参数，告诉它重点保留什么：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact 保留所有代码修改记录和文件路径，丢弃分析过程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>⚠️ <code>/compact</code> 是有损压缩，细节可能丢失，适合&quot;换挡&quot;时使用。</p></blockquote><hr><h3 id="技巧-2-用-clear-彻底清空-任务切换必做" tabindex="-1">技巧 2：用 <code>/clear</code> 彻底清空（任务切换必做） <a class="header-anchor" href="#技巧-2-用-clear-彻底清空-任务切换必做" aria-label="Permalink to &quot;技巧 2：用 `/clear` 彻底清空（任务切换必做）&quot;">​</a></h3><p>完全切换任务时用 <code>/clear</code>，比如从项目 A 切到项目 B，或者从写功能切到修 Bug。<strong>不要把上一个任务的上下文带进新任务</strong>，这是最容易被忽视的浪费。</p><p>推荐习惯：把 <code>/clear</code> 当成 Git commit 一样，<strong>完成一个功能点就清理一次</strong>。</p><hr><h3 id="技巧-3-精准描述需求-别让-claude-自己去找" tabindex="-1">技巧 3：精准描述需求，别让 Claude 自己去找 <a class="header-anchor" href="#技巧-3-精准描述需求-别让-claude-自己去找" aria-label="Permalink to &quot;技巧 3：精准描述需求，别让 Claude 自己去找&quot;">​</a></h3><p><strong>❌ 低效写法：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>登录有问题，帮我看看</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Claude 会开始 Glob 扫目录、Grep 搜关键词、Read 读文件，一轮探索下来消耗 15000～25000 Token。</p><p><strong>✅ 高效写法：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查看 src/auth/login.ts 第 45 行，JWT 验证里 exp 字段没检查，</span></span>\n<span class="line"><span>加上过期时间校验，过期时抛 AuthExpiredError</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Claude 只需要 Read 一次文件、Edit 一次代码，3000～5000 Token 搞定，<strong>节省 70%～80%</strong>。</p><p><strong>万能提问公式：做什么 + 在哪个文件 + 具体改什么 + 用什么方式</strong></p><hr><h3 id="技巧-4-用-claudeignore-排除无关文件" tabindex="-1">技巧 4：用 <code>.claudeignore</code> 排除无关文件 <a class="header-anchor" href="#技巧-4-用-claudeignore-排除无关文件" aria-label="Permalink to &quot;技巧 4：用 `.claudeignore` 排除无关文件&quot;">​</a></h3><p>大模型按输入 Token 长度收费。让 Claude 读 <code>node_modules</code>、<code>dist</code>、<code>.git</code> 等文件夹是纯粹的浪费。</p><p>在项目根目录创建 <code>.claudeignore</code> 文件：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/</span></span>\n<span class="line"><span>dist/</span></span>\n<span class="line"><span>.git/</span></span>\n<span class="line"><span>*.log</span></span>\n<span class="line"><span>coverage/</span></span>\n<span class="line"><span>.next/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>实测可减少 <strong>25%</strong> 的输入 Token。</p><hr><h3 id="技巧-5-90-的任务用-sonnet-难题才用-opus" tabindex="-1">技巧 5：90% 的任务用 Sonnet，难题才用 Opus <a class="header-anchor" href="#技巧-5-90-的任务用-sonnet-难题才用-opus" aria-label="Permalink to &quot;技巧 5：90% 的任务用 Sonnet，难题才用 Opus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐模型</th><th>原因</th></tr></thead><tbody><tr><td>日常功能开发、代码补全</td><td><strong>Sonnet</strong></td><td>能力已足够，价格低 5 倍</td></tr><tr><td>复杂架构设计、多文件重构</td><td><strong>Opus</strong></td><td>真正需要顶级推理时再用</td></tr><tr><td>简单格式化、文档生成</td><td><strong>Haiku</strong></td><td>极简任务，极低成本</td></tr></tbody></table><p>切换命令：<code>/model sonnet</code> / <code>/model opus</code> / <code>/model haiku</code></p><hr><h3 id="技巧-6-保持-claude-md-精简" tabindex="-1">技巧 6：保持 CLAUDE.md 精简 <a class="header-anchor" href="#技巧-6-保持-claude-md-精简" aria-label="Permalink to &quot;技巧 6：保持 CLAUDE.md 精简&quot;">​</a></h3><p>CLAUDE.md 会随<strong>每一条消息</strong>一起发送，文件越长，每次都多花 Token。</p><ul><li>只放最核心的规则（技术栈、编码规范、注意事项）</li><li>不常用的规则移到 skill 文件，按需加载</li><li>单个文件控制在 500 行以内</li></ul><blockquote><p>有位开发者测试：CLAUDE.md 从 200 行精简到 50 行后，日均 Token 消耗降低了约 15%。</p></blockquote><hr><h3 id="技巧-7-利用-prompt-caching-缓存重复内容" tabindex="-1">技巧 7：利用 Prompt Caching 缓存重复内容 <a class="header-anchor" href="#技巧-7-利用-prompt-caching-缓存重复内容" aria-label="Permalink to &quot;技巧 7：利用 Prompt Caching 缓存重复内容&quot;">​</a></h3><p>当你在同一会话或短时间内发送包含相同上下文的请求时，API 会自动命中缓存：</p><ul><li><strong>缓存读取价格 = 基础输入价格的 1/10</strong></li><li>缓存有效期：5 分钟内连续操作不失效</li></ul><p><strong>实用建议：</strong> 尽量集中连续完成相关任务，避免超过 5 分钟的闲置，否则缓存失效、下次重新计费。</p><hr><h2 id="三、月成本估算参考" tabindex="-1">三、月成本估算参考 <a class="header-anchor" href="#三、月成本估算参考" aria-label="Permalink to &quot;三、月成本估算参考&quot;">​</a></h2><p>以中等强度使用（每周 40 次会话）为例：</p><table tabindex="0"><thead><tr><th>方案</th><th>模型</th><th>优化程度</th><th>月成本</th></tr></thead><tbody><tr><td>不优化</td><td>Sonnet</td><td>无</td><td>~$60</td></tr><tr><td>基础优化</td><td>Sonnet</td><td>技巧 1-4</td><td>~$30</td></tr><tr><td>充分优化</td><td>Sonnet</td><td>全部 7 条</td><td><strong>~$20</strong></td></tr><tr><td>重型任务</td><td>Opus（少量）</td><td>充分优化</td><td>~$35-50</td></tr></tbody></table><hr><h2 id="四、一句话总结" tabindex="-1">四、一句话总结 <a class="header-anchor" href="#四、一句话总结" aria-label="Permalink to &quot;四、一句话总结&quot;">​</a></h2><blockquote><p><strong>完成任务就 <code>/clear</code>，对话变长就 <code>/compact</code>，问题写清楚别让 Claude 自己找</strong>——这三个习惯，立刻省下 50% 以上的 Token 消耗。</p></blockquote><hr><h2 id="🐼-熊猫算力平台提示" tabindex="-1">🐼 熊猫算力平台提示 <a class="header-anchor" href="#🐼-熊猫算力平台提示" aria-label="Permalink to &quot;🐼 熊猫算力平台提示&quot;">​</a></h2><p>通过熊猫算力调用 Claude API，享受与官方同步的最新模型，国内直连，无需海外信用卡。 模型选错了也会多花冤枉钱——合理搭配 Sonnet + Opus，才是真正的省钱之道。</p><p>👉 <a href="https://pandatoken.cn" target="_blank" rel="noreferrer">查看熊猫算力模型定价 →</a></p>',64)])])}const b=a(d,[["render",s]]);export{u as __pageData,b as default};
